using Microsoft.CodeAnalysis;
using XamlG.Compiler;
using XamlG.Roslyn;
namespace XamlG.CSharp;
internal sealed class ObjectEmitter
{
    private readonly EmissionContext _context;
    private readonly ValueEmitter _values;
    private readonly AssignmentEmitter _assignments;
    public ObjectEmitter(EmissionContext context) { _context = context; _values = new(context, this); _assignments = new(context, this, _values); }
    public void EmitContext(string variable, string outer, string root)
    {
        var baseUri = _context.Document.Options.BaseUri is { } uri ? "new global::System.Uri(" + CSharpNames.Literal(uri) + ", global::System.UriKind.RelativeOrAbsolute)" : "null";
        var factory = _context.Document.Runtime.InnerServiceProviderFactory;
        if (factory != null) outer = factory.ContainingType.CSharpName() + "." + CSharpNames.Method(factory) + "(" + outer + ")";
        var serviceTypes = _context.Document.Runtime.Services.Select(s => "__type == typeof(" + s.InterfaceType.CSharpName() + ")").ToArray();
        var services = serviceTypes.Length == 0 ? "null" : "static (__frame, __type) => (" + string.Join(" || ", serviceTypes) + ") ? new " + _context.ServicesType + "(__frame) : null";
        _context.Writer.Line("var " + variable + " = new " + CSharpNames.Context + "(" + outer + ", " + root + ", " + baseUri + ", " + services + ");");
    }
    public string Emit(BoundObject value, string parentContext, string? existing, Action<string>? consume)
    {
        _context.Cancellation.ThrowIfCancellationRequested(); var writer = _context.Writer;
        var variable = existing ?? (value.IsRoot ? _context.RootVariable : _context.Temporary("object"));
        if (existing == null)
        {
            var arguments = value.Arguments.Select(a => _values.Emit(a, parentContext)).ToArray();
            string creation;
            if (value.FactoryMethod != null) creation = value.FactoryMethod.ContainingType.CSharpName() + "." + CSharpNames.Method(value.FactoryMethod) + "(" + string.Join(", ", arguments) + ")";
            else creation = "new " + value.Type.CSharpName() + "(" + string.Join(", ", arguments) + ")";
            writer.Line("var " + variable + " = " + creation + ";");
        }
        var frame = _context.Temporary("context");
        writer.Line("var " + frame + " = " + parentContext + ".Push(" + variable + ", " + CSharpNames.Literal(value.Key) + ");");
        if (value.Name != null)
        {
            writer.Line(frame + ".RegisterName(" + CSharpNames.Literal(value.Name) + ", " + variable + ");");
            if (_context.Document.ClassSymbol != null && _context.Document.Options.GenerateNamedFields && value.NameScopeId == _context.Document.Root!.NameScopeId)
                writer.Line(_context.RootVariable + "." + CSharpNames.Identifier(value.Name) + " = " + variable + ";");
        }
        if (value.SupportsInitialize) writer.Line("((global::System.ComponentModel.ISupportInitialize)" + variable + ").BeginInit();");
        if (value.UsableDuringInitialization) consume?.Invoke(variable);
        var collections = new Dictionary<ISymbol, string>(SymbolEqualityComparer.Default);
        foreach (var assignment in value.Assignments)
            _context.Map(assignment.Span, () => _assignments.Emit(assignment, value, variable, frame, collections));
        if (value.SupportsInitialize) writer.Line("((global::System.ComponentModel.ISupportInitialize)" + variable + ").EndInit();");
        if (!value.UsableDuringInitialization) consume?.Invoke(variable);
        return variable;
    }
}

using Microsoft.CodeAnalysis;
using XamlG.Compiler;
using XamlG.Roslyn;
namespace XamlG.CSharp;
internal sealed class ValueEmitter
{
    private readonly EmissionContext _context;
    private readonly ObjectEmitter _objects;
    public ValueEmitter(EmissionContext context, ObjectEmitter objects) { _context = context; _objects = objects; }
    public string Emit(BoundExpression value, string frame)
    {
        _context.Cancellation.ThrowIfCancellationRequested();
        switch (value)
        {
            case BoundConstantExpression constant: return CSharpNames.Constant(constant.Value);
            case BoundEnumExpression enumeration: return "(" + string.Join(" | ", enumeration.Fields.Select(f => f.ContainingType.CSharpName() + "." + CSharpNames.Identifier(f.Name))) + ")";
            case BoundCastExpression cast: return "((" + cast.TargetType.CSharpName() + ")(" + Emit(cast.Value, frame) + "))";
            case BoundTypeExpression type: return "typeof(" + type.ReferencedType.CSharpName() + ")";
            case BoundStaticExpression field: return field.Member.ContainingType.CSharpName() + "." + CSharpNames.Identifier(field.Member.Name);
            case BoundServiceExpression service: return service.ServiceType.HasMetadataName(ClrNames.IServiceProvider) ? frame : "((" + service.ServiceType.CSharpName() + ")" + frame + ".GetService(typeof(" + service.ServiceType.CSharpName() + "))!)";
            case BoundReferenceExpression reference: return frame + ".ResolveName<" + (reference.Type?.CSharpName() ?? "object") + ">(" + CSharpNames.Literal(reference.Name) + ")";
            case BoundObjectExpression obj: return _objects.Emit(obj.Object, frame, null, null);
            case BoundArrayExpression array:
            { var items = array.Values.Select(v => Emit(v, frame)).ToArray(); return "new " + array.ArrayType.ElementType.CSharpName() + "[] { " + string.Join(", ", items) + " }"; }
            case BoundNewExpression creation:
            { var args = creation.Arguments.Select(a => Emit(a, frame)).ToArray(); return "new " + creation.Constructor.ContainingType.CSharpName() + "(" + string.Join(", ", args) + ")"; }
            case BoundCallExpression call:
            {
                var receiver = call.Method.IsStatic ? call.Method.ContainingType.CSharpName() : call.Receiver == null ? _context.RootVariable : Emit(call.Receiver, frame);
                var args = call.Arguments.Select(a => Emit(a, frame)).ToArray();
                return receiver + "." + CSharpNames.Method(call.Method) + "(" + string.Join(", ", args) + ")";
            }
            case BoundParseExpression parse:
                return parse.Method.ContainingType.CSharpName() + "." + CSharpNames.Method(parse.Method) + "(" + CSharpNames.Literal(parse.Text) + (parse.Method.Parameters.Length == 2 ? ", " + CSharpNames.InvariantCulture : string.Empty) + ")";
            case BoundConverterExpression converter:
                return "((" + converter.ValueType.CSharpName() + ")new " + converter.Converter.CSharpName() + "().ConvertFrom(" + frame + ", " + CSharpNames.InvariantCulture + ", " + CSharpNames.Literal(converter.Text) + " )!)";
            case BoundMarkupExpression markup:
            {
                var extension = _objects.Emit(markup.Extension, frame, null, null);
                return extension + "." + CSharpNames.Method(markup.Method) + "(" + (markup.Method.Parameters.Length == 0 ? string.Empty : frame) + ")";
            }
            case BoundDeferredExpression deferred: return Deferred(deferred, frame);
            case BoundRawExpression raw: return ExpandTrusted(raw.CSharp, frame, frame + ".TargetObject!");
            default: _context.Error("The backend does not recognize expression '" + value.GetType().Name + "'.", value.Span); return "default!";
        }
    }
    public string ExpandTrusted(string source, string frame, string target) => source.Replace("$context", frame).Replace("$target", target).Replace("$root", _context.RootVariable);
    private string Deferred(BoundDeferredExpression deferred, string parentFrame)
    {
        var writer = _context.Writer; var name = _context.Temporary("factory"); var frame = _context.Temporary("deferredContext");
        var incoming = _context.Temporary("incoming"); var root = _context.Temporary("ownerRoot");
        var returnType = deferred.FactoryReturnType?.CSharpName() ?? "object";
        writer.Open((deferred.UsesFunctionPointer ? "static " : string.Empty) + returnType + " " + name + "(" + CSharpNames.Provider + "? " + incoming + ")");
        if (deferred.UsesFunctionPointer) writer.Line("var " + frame + " = (" + incoming + " as " + CSharpNames.Context + " ?? new " + CSharpNames.Context + "(" + incoming + ")).CreateDeferredScope(" + incoming + ");");
        else writer.Line("var " + frame + " = " + parentFrame + ".CreateDeferredScope(" + incoming + ");");
        writer.Line("var " + root + " = (" + _context.Document.Root!.Type.CSharpName() + ")" + frame + ".RootObject!;");
        var saved = _context.RootVariable; _context.RootVariable = root;
        try
        {
            var content = Emit(deferred.Content, frame); var result = _context.Temporary("template");
            writer.Line(returnType + " " + result + " = " + content + ";"); writer.Line(frame + ".Complete(" + result + "!);"); writer.Line("return " + result + ";");
        }
        finally { _context.RootVariable = saved; }
        writer.Close();
        if (deferred.Customizer != null)
        {
            var factory = deferred.UsesFunctionPointer ? "(global::System.IntPtr)(delegate* managed<" + CSharpNames.Provider + ", " + returnType + ">)&" + name : "(" + deferred.Customizer.Parameters[0].Type.CSharpName() + ")" + name;
            if (deferred.UsesFunctionPointer)
            {
                var result = _context.Temporary("deferred"); writer.Line(deferred.TargetType.CSharpName() + " " + result + ";"); writer.Open("unsafe");
                writer.Line(result + " = " + deferred.Customizer.ContainingType.CSharpName() + "." + CSharpNames.Method(deferred.Customizer) + "(" + factory + ", " + parentFrame + ");"); writer.Close(); return result;
            }
            return deferred.Customizer.ContainingType.CSharpName() + "." + CSharpNames.Method(deferred.Customizer) + "(" + factory + ", " + parentFrame + ")";
        }
        return "(" + deferred.TargetType.CSharpName() + ")" + name;
    }
}

using Microsoft.CodeAnalysis;
using XamlG.Compiler;
using XamlG.Roslyn;
namespace XamlG.CSharp;
internal sealed class AssignmentEmitter
{
    private readonly EmissionContext _context;
    private readonly ObjectEmitter _objects;
    private readonly ValueEmitter _values;
    public AssignmentEmitter(EmissionContext context, ObjectEmitter objects, ValueEmitter values) { _context = context; _objects = objects; _values = values; }
    public void Emit(BoundAssignment assignment, BoundObject owner, string target, string frame, Dictionary<ISymbol, string> collections)
    {
        if (BoundTraversal.Expressions(assignment).Any(BoundTraversal.ContainsReference))
        { _context.Writer.Open(frame + ".Defer(() =>"); EmitCore(assignment, owner, target, frame, new(SymbolEqualityComparer.Default)); _context.Writer.Close(");"); }
        else EmitCore(assignment, owner, target, frame, collections);
    }
    private void EmitCore(BoundAssignment assignment, BoundObject owner, string target, string frame, Dictionary<ISymbol, string> collections)
    {
        var writer = _context.Writer;
        switch (assignment)
        {
            case BoundSetAssignment set:
            {
                collections.Remove(set.Member.Symbol); var valueFrame = ForTarget(set.Member, target, frame);
                void Assign(string value)
                {
                    Set(set.Member, target, value);
                    if (set.Member.Getter != null && set.Member.Setter != null && !set.Member.Setter.IsInitOnly)
                        writer.Line(frame + ".Session.RegisterProperty<" + set.Member.ValueType.CSharpName() + ">(" + CSharpNames.Literal(owner.Key) + ", " + CSharpNames.Literal(set.Member.Name) + ", () => " + Get(set.Member, target) + ", __value => { " + SetExpression(set.Member, target, "__value") + "; });");
                }
                if (set.Value is BoundObjectExpression child) _objects.Emit(child.Object, valueFrame, null, Assign); else Assign(_values.Emit(set.Value, valueFrame));
                break;
            }
            case BoundAddAssignment add:
            {
                var receiver = target; var valueFrame = frame;
                if (add.Collection != null)
                {
                    valueFrame = ForTarget(add.Collection, target, frame);
                    if (!collections.TryGetValue(add.Collection.Symbol, out receiver!))
                    { receiver = _context.Temporary("collection"); writer.Line("var " + receiver + " = " + Get(add.Collection, target) + ";"); collections.Add(add.Collection.Symbol, receiver); }
                }
                var arguments = new List<string>();
                for (var i = 0; i < add.Arguments.Length - 1; i++) arguments.Add(_values.Emit(add.Arguments[i], valueFrame));
                var last = add.Arguments[add.Arguments.Length - 1];
                void Add(string value) => writer.Line("((" + add.AddMethod.ContainingType.CSharpName() + ")" + receiver + ")." + CSharpNames.Method(add.AddMethod) + "(" + string.Join(", ", arguments.Concat(new[] { value })) + ");");
                if (last is BoundObjectExpression child) _objects.Emit(child.Object, valueFrame, null, Add); else Add(_values.Emit(last, valueFrame));
                break;
            }
            case BoundEventAssignment ev:
            {
                var handler = _context.Temporary("handler"); writer.Line(ev.Event.ValueType.CSharpName() + " " + handler + " = " + _context.RootVariable + "." + CSharpNames.Identifier(ev.HandlerName) + ";");
                if (ev.Event.Kind == BoundMemberKind.Event)
                {
                    writer.Line(target + "." + CSharpNames.Identifier(ev.Event.Name) + " += " + handler + ";");
                    writer.Line(frame + ".Session.TrackCleanup(() => " + target + "." + CSharpNames.Identifier(ev.Event.Name) + " -= " + handler + ");");
                }
                else
                {
                    var method = ev.Event.Setter!; writer.Line(method.ContainingType.CSharpName() + "." + CSharpNames.Method(method) + "(" + target + ", " + handler + ");");
                    var remove = method.ContainingType.GetMembers("Remove" + ev.Event.Name + "Handler").OfType<IMethodSymbol>().FirstOrDefault(m => m.IsStatic && m.Parameters.Length == 2);
                    if (remove != null) writer.Line(frame + ".Session.TrackCleanup(() => " + remove.ContainingType.CSharpName() + "." + CSharpNames.Method(remove) + "(" + target + ", " + handler + "));");
                }
                break;
            }
            case BoundCallAssignment call:
            {
                var args = call.Arguments.Select(a => _values.Emit(a, frame)).ToList(); if (call.IncludeTarget) args.Insert(0, target);
                writer.Line((call.Method.IsStatic ? call.Method.ContainingType.CSharpName() : target) + "." + CSharpNames.Method(call.Method) + "(" + string.Join(", ", args) + ");"); break;
            }
            case BoundDynamicSetAssignment dynamicSet: Dynamic(dynamicSet, target, frame); break;
            case BoundAdaptedSetAssignment adapted:
            {
                var value = _context.Temporary("adapted"); writer.Line("object? " + value + " = " + _values.Emit(adapted.Value, ForTarget(adapted.Member, target, frame)) + ";");
                var first = true;
                foreach (var type in adapted.AdaptedTypes)
                {
                    var typed = _context.Temporary("value"); writer.Open((first ? "if" : "else if") + " (" + value + " is " + type.CSharpName() + " " + typed + ")");
                    var args = new List<string> { target };
                    if (adapted.Adapter.Parameters.Length == 3) args.Add(adapted.Member.TargetDescriptor == null ? _context.Descriptor(adapted.Member) : _values.Emit(adapted.Member.TargetDescriptor, frame));
                    args.Add(typed); writer.Line(adapted.Adapter.ContainingType.CSharpName() + "." + CSharpNames.Method(adapted.Adapter) + "(" + string.Join(", ", args) + ");"); writer.Close(); first = false;
                }
                writer.Open(first ? "" : "else"); Set(adapted.Member, target, "(" + adapted.Member.ValueType.CSharpName() + ")" + value + "!"); writer.Close(); break;
            }
            case BoundRawAssignment raw: writer.Line(_values.ExpandTrusted(raw.CSharp, frame, target)); break;
            default: _context.Error("The backend does not recognize assignment '" + assignment.GetType().Name + "'.", assignment.Span); break;
        }
    }
    private void Dynamic(BoundDynamicSetAssignment assignment, string target, string frame)
    {
        var writer = _context.Writer; var value = _context.Temporary("dynamic"); writer.Line("object? " + value + " = " + _values.Emit(assignment.Value, ForTarget(assignment.Target, target, frame)) + ";");
        var first = true;
        foreach (var candidate in assignment.Candidates)
        {
            var local = _context.Temporary("candidate");
            writer.Open((first ? "if" : "else if") + " (" + value + " is " + candidate.ValueType.CSharpName() + " || " + (candidate.AllowRuntimeNull ? value + " is null" : "false") + ")");
            writer.Line("var " + local + " = (" + candidate.ValueType.CSharpName() + ")" + value + "!;");
            if (candidate is BoundPropertyValueSetter property) Set(property.Member, target, local);
            else if (candidate is BoundMethodValueSetter method)
            {
                var receiver = target; foreach (var propertySymbol in method.ReceiverPath) receiver += "." + CSharpNames.Identifier(propertySymbol.Name);
                var args = method.IncludeTarget ? target + ", " + local : local;
                writer.Line((method.Method.IsStatic ? method.Method.ContainingType.CSharpName() : "((" + method.Method.ContainingType.CSharpName() + ")" + receiver + ")") + "." + CSharpNames.Method(method.Method) + "(" + args + ");");
            }
            writer.Close(); first = false;
        }
        writer.Line((first ? string.Empty : "else ") + "throw new global::System.InvalidCastException(\"No XAML setter accepts the runtime value.\");");
    }
    private string ForTarget(BoundMember member, string target, string parent)
    {
        var descriptor = member.TargetDescriptor == null ? _context.Descriptor(member) : _values.Emit(member.TargetDescriptor, parent);
        var frame = _context.Temporary("target"); _context.Writer.Line("var " + frame + " = " + parent + ".ForTarget(" + target + ", " + descriptor + ");"); return frame;
    }
    private static string Get(BoundMember member, string target) => member.Kind == BoundMemberKind.AttachedProperty ? member.Getter!.ContainingType.CSharpName() + "." + CSharpNames.Method(member.Getter) + "(" + target + ")" : target + "." + CSharpNames.Identifier(member.Name);
    private string SetExpression(BoundMember member, string target, string value)
    {
        if (member.Setter?.IsInitOnly == true) return _context.InitSetter(member.Setter) + "(" + (member.Setter.ContainingType.IsValueType ? "ref " : string.Empty) + target + ", " + value + ")";
        return member.Kind == BoundMemberKind.AttachedProperty ? member.Setter!.ContainingType.CSharpName() + "." + CSharpNames.Method(member.Setter) + "(" + target + ", " + value + ")" : target + "." + CSharpNames.Identifier(member.Name) + " = " + value;
    }
    private void Set(BoundMember member, string target, string value) => _context.Writer.Line(SetExpression(member, target, value) + ";");
}

using Microsoft.CodeAnalysis;
using XamlG.Compiler;
using XamlG.Roslyn;
namespace XamlG.CSharp;
internal sealed class ServiceContractEmitter
{
    private readonly EmissionContext _context;
    public ServiceContractEmitter(EmissionContext context) => _context = context;
    public void Emit()
    {
        var contracts = _context.Document.Runtime.Services; if (contracts.Length == 0) return; var writer = _context.Writer;
        writer.Open("private sealed class " + _context.ServicesType + " : " + string.Join(", ", contracts.Select(s => s.InterfaceType.CSharpName()).Distinct()));
        writer.Line("private readonly " + CSharpNames.Context + " _context;");
        writer.Line("public " + _context.ServicesType + "(" + CSharpNames.Context + " context) => _context = context;");
        var emitted = new HashSet<ISymbol>(SymbolEqualityComparer.Default);
        foreach (var contract in contracts)
            foreach (var member in contract.InterfaceType.Members())
            {
                if (member.IsStatic || !emitted.Add(member) || member is IMethodSymbol { MethodKind: MethodKind.PropertyGet or MethodKind.PropertySet }) continue;
                if (member is not IPropertySymbol property || property.IsIndexer)
                { _context.Error($"Runtime contract member '{member}' is not a supported service property.", new(0, 0)); continue; }
                var expression = contract.Mapping.Kind switch
                {
                    XamlServiceKind.RootObject when property.Name == "RootObject" => "_context.RootObject",
                    XamlServiceKind.RootObject when property.Name == "IntermediateRootObject" => "_context.IntermediateRootObject",
                    XamlServiceKind.ProvideValueTarget when property.Name == "TargetObject" => "_context.TargetObject",
                    XamlServiceKind.ProvideValueTarget when property.Name == "TargetProperty" => "_context.TargetProperty",
                    XamlServiceKind.ParentStack when property.Name == "Parents" => "_context.Parents",
                    XamlServiceKind.UriContext when property.Name == "BaseUri" => "_context.BaseUri",
                    _ => null
                };
                if (expression == null) { _context.Error($"Service property '{property}' has no configured value mapping.", new(0, 0)); expression = "default"; }
                var getter = property.GetMethod == null ? string.Empty : "get => (" + property.Type.CSharpName() + ")" + expression + "!;";
                var setter = property.SetMethod == null ? string.Empty : contract.Mapping.Kind == XamlServiceKind.UriContext ? "set => _context.BaseUri = value;" : "set => throw new global::System.NotSupportedException();";
                writer.Line(property.Type.CSharpName() + " " + property.ContainingType.CSharpName() + "." + CSharpNames.Identifier(property.Name) + " { " + getter + " " + setter + " }");
            }
        writer.Close();
    }
}
